modes.shape:
enum CrewKind {
  Worker, Sailor, Hand, Captain, Lookout
}

enum TicketStatus {
  Todo, Blocked, InProgress, InQa, Done, Cancelled
}

enum PipelineStatus {
  Running, Success, Failed, Canceled, Manual
}

enum Classification {
  Clean,   // all blockers terminal -> fork master
  Stacked, // one in-flight parent -> stack, 1 deep
  Blocked, // a dependency isn't ready -> wait
  Hold,    // held off frontier (groom-gate/operator)
}

enum CogState {
  Worker(WorkerState),
  Sailor(SailorState),
  Hand(HandState),
}
enum WorkerState { Started, Implementing,
  Concluded, Escalated, Anchored }
enum SailorState { Started, Finishing, Sleeping,
  InDraft, Merged, Closed, Escalated, Anchored }
enum HandState { Awaiting, Implementing,
  Concluded, Anchored }

enum EntityKind {
  Session, Ticket, Ship, Escalation,
  Ticker, Convoy, Lookout
}

struct Report {
  session: SessionId,          // PK = FK
  state: CogState,             // Worker/Sailor/Hand
  last_action: Option<String>,
  reported_at: Timestamp,
}

struct Packet {
  order: Option<Order>,
  ship: Option<Ship>,
  snapshot: Option<ShipSnapshot>,
  ticket: Option<Ticket>,
}

struct ConvoyView {
  convoy: ConvoyKey,
  tickets: Vec<ConvoyTicketView>,
}
struct ConvoyTicketView {
  key: TicketKey,
  status: Option<TicketStatus>,
  classification: Option<Classification>,
  dispatched: bool,
  live_cog: Option<CrewKind>,
  ship_state: Option<ShipState>,
}

struct ShipView {
  ship: Ship,
  snapshot: Option<ShipSnapshot>,
}

struct ReviewState {
  open_threads: i64,
  floating_notes: Vec<FloatingNote>,
}
struct FloatingNote {
  id: i64,
  author: Option<String>,
  created_at: String,
  body: String,
}
